import Foundation
import Vapor
import Compression

struct UploadConfig {
    static let maxRetries = 3
    static let rateLimitWindow: TimeInterval = 60
    static let maxRequestsPerWindow = 10
    static let maxCompressedSize: Int = 10 * 1024 * 1024  // 10MB compressed
    static let maxDecompressedSize: Int = 100 * 1024 * 1024  // 100MB decompressed
    static let chunkSize: Int = 65536
}

class RateLimiter {
    private var requests: [String: [(Date, Int)]] = [:]
    private let lock = NSLock()

    func shouldAllow(clientIP: String, retryCount: Int) -> Bool {
        lock.lock()
        defer { lock.unlock() }

        let now = Date()
        let windowStart = now.addingTimeInterval(-UploadConfig.rateLimitWindow)

        // Prune all stale entries across every client to prevent unbounded
        // memory growth from rotating/spoofed source addresses.
        for (ip, entries) in requests {
            let filtered = entries.filter { $0.0 > windowStart }
            if filtered.isEmpty {
                requests.removeValue(forKey: ip)
            } else {
                requests[ip] = filtered
            }
        }

        let currentCount = requests[clientIP]?.count ?? 0
        // Retries don't increase the rate limit - fixed window
        let effectiveLimit = UploadConfig.maxRequestsPerWindow

        if currentCount >= effectiveLimit {
            return false
        }

        requests[clientIP, default: []].append((now, retryCount))
        return true
    }
}

class DecompressionValidator {
    private var totalBytesDecompressed: Int = 0
    private let maxRatio: Double = 10.0
    private let compressedSize: Int

    init(compressedSize: Int) {
        self.compressedSize = compressedSize
    }

    func validateChunk(decompressedBytes: Int) -> Bool {
        totalBytesDecompressed += decompressedBytes
        guard compressedSize > 0 else { return false }
        let currentRatio = Double(totalBytesDecompressed) / Double(compressedSize)
        return totalBytesDecompressed <= UploadConfig.maxDecompressedSize && currentRatio <= maxRatio
    }

    func validateRatio() -> Bool {
        guard compressedSize > 0 else { return false }
        let ratio = Double(totalBytesDecompressed) / Double(compressedSize)
        return ratio <= maxRatio
    }

    func currentTotal() -> Int {
        return totalBytesDecompressed
    }
}

func decompressData(compressedData: Data, validator: DecompressionValidator) throws -> Data {
    var decompressed = Data()
    let bufferSize = UploadConfig.chunkSize

    try compressedData.withUnsafeBytes { rawBuffer in
        guard let baseAddress = rawBuffer.baseAddress else { return }
        let sourceSize = rawBuffer.count

        let destinationBuffer = UnsafeMutablePointer<UInt8>.allocate(capacity: bufferSize)
        defer { destinationBuffer.deallocate() }

        let stream = UnsafeMutablePointer<compression_stream>.allocate(capacity: 1)
        defer { stream.deallocate() }

        var status = compression_stream_init(stream, COMPRESSION_STREAM_DECODE, COMPRESSION_ZLIB)
        guard status != COMPRESSION_STATUS_ERROR else {
            throw Abort(.badRequest, reason: "Failed to initialize decompression")
        }
        defer { compression_stream_destroy(stream) }

        stream.pointee.src_ptr = baseAddress.assumingMemoryBound(to: UInt8.self)
        stream.pointee.src_size = sourceSize
        stream.pointee.dst_ptr = destinationBuffer
        stream.pointee.dst_size = bufferSize

        repeat {
            status = compression_stream_process(stream, 0)

            switch status {
            case COMPRESSION_STATUS_OK, COMPRESSION_STATUS_END:
                let outputSize = bufferSize - stream.pointee.dst_size
                if outputSize > 0 {
                    if !validator.validateChunk(decompressedBytes: outputSize) {
                        throw Abort(.badRequest, reason: "Decompressed size exceeds limit")
                    }
                    decompressed.append(destinationBuffer, count: outputSize)
                }
                stream.pointee.dst_ptr = destinationBuffer
                stream.pointee.dst_size = bufferSize
            case COMPRESSION_STATUS_ERROR:
                throw Abort(.badRequest, reason: "Decompression error")
            default:
                break
            }
        } while status == COMPRESSION_STATUS_OK
    }

    return decompressed
}

func handleUpload(app: Application) {
    let rateLimiter = RateLimiter()

    app.post("upload") { req -> Response in
        let clientIP = req.remoteAddress?.description ?? "unknown"
        let retryHeader = req.headers.first(name: "X-Retry-Count") ?? "0"
        let retryCount = min(Int(retryHeader) ?? 0, UploadConfig.maxRetries)

        guard rateLimiter.shouldAllow(clientIP: clientIP, retryCount: retryCount) else {
            throw Abort(.tooManyRequests)
        }

        guard let body = req.body.data else {
            throw Abort(.badRequest, reason: "No body")
        }

        let compressedData = Data(buffer: body)

        guard compressedData.count <= UploadConfig.maxCompressedSize else {
            throw Abort(.payloadTooLarge)
        }

        let validator = DecompressionValidator(compressedSize: compressedData.count)
        let decompressed = try decompressData(compressedData: compressedData, validator: validator)

        // Ratio check is redundant here since validateChunk already enforces it
        guard validator.validateRatio() else {
            throw Abort(.badRequest, reason: "Suspicious compression ratio")
        }

        // Process the decompressed data
        let hash = SHA256.hash(data: decompressed)
        return Response(status: .ok, body: .init(string: "Processed: \(hash.description)"))
    }
}
